import rawMajors from "@/data/majors.json";

/**
 * Each school's majors, largest first, generated by scripts/import-programs.mjs
 * (with --cip) from the IPEDS Completions survey. Import this from server
 * components only: the file covers every school, and a profile page needs one
 * school's list, which the page passes down as a prop.
 */
interface MajorsFile {
  source: string;
  year: string;
  names: Record<string, string>;
  byCollege: Record<string, string[]>;
}

const majors = rawMajors as unknown as MajorsFile;

export interface Major {
  /** Federal CIP 2020 code, e.g. "14.1901". What ties a major to an interest's field. */
  cip: string;
  name: string;
}

export interface SchoolMajors {
  /** Ordered by bachelor's degrees awarded, largest first. */
  list: Major[];
  source: string;
  year: string;
}

/**
 * A school's majors in order. Two federal codes can share a reworded name
 * (several "other" categories do); the smaller is dropped so a name never
 * appears twice in one list.
 */
export function getSchoolMajors(collegeId: string): SchoolMajors {
  const seen = new Set<string>();
  const list: Major[] = [];
  for (const cip of majors.byCollege[collegeId] ?? []) {
    const name = majors.names[cip];
    if (!name || seen.has(name)) continue;
    seen.add(name);
    list.push({ cip, name });
  }
  return { list, source: majors.source, year: majors.year };
}
